CREATE TABLE IF NOT EXISTS finance_allocation_sets ( id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, organization_id BIGINT UNSIGNED NOT NULL, dv_id BIGINT UNSIGNED NOT NULL, bank_account_id BIGINT UNSIGNED NOT NULL, accounting_version_id BIGINT UNSIGNED NOT NULL, revision INT UNSIGNED NOT NULL, active_dv_id BIGINT UNSIGNED NULL, state VARCHAR(16) NOT NULL, predecessor_id BIGINT UNSIGNED NULL, gross_cents BIGINT UNSIGNED NOT NULL, tax_cents BIGINT UNSIGNED NOT NULL, net_cents BIGINT UNSIGNED NOT NULL, retained_cents BIGINT UNSIGNED NOT NULL DEFAULT 0, evidence_reference VARCHAR(255) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY uq_fas_active_dv (active_dv_id), UNIQUE KEY uq_fas_dv_revision (dv_id, revision), KEY ix_fas_scope (organization_id, bank_account_id), CONSTRAINT fk_fas_org FOREIGN KEY (organization_id) REFERENCES organizations(id), CONSTRAINT fk_fas_dv FOREIGN KEY (dv_id) REFERENCES disbursement_vouchers(id), CONSTRAINT fk_fas_bank FOREIGN KEY (bank_account_id) REFERENCES bank_accounts(id), CONSTRAINT fk_fas_accounting FOREIGN KEY (accounting_version_id) REFERENCES dv_accounting_versions(id), CONSTRAINT fk_fas_actor FOREIGN KEY (created_by) REFERENCES users(id), CONSTRAINT fk_fas_previous FOREIGN KEY (predecessor_id) REFERENCES finance_allocation_sets(id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
